// Default cartoon avatar assigned when a candidate registers or has no custom avatar
export const DEFAULT_CARTOON_AVATAR = CARTOON_AVATARS[0].dataUri;

/**
 * Check if a picture string is a legacy stock Unsplash photo portrait.
 * These are replaced by our modern cartoon avatars by default.
 */
export function isLegacyStockAvatar(picture?: string | null): boolean {
  if (!picture) return false;
  return picture.includes('images.unsplash.com');
}

/**
 * Returns a resilient avatar source URL.
 * Returns DEFAULT_CARTOON_AVATAR if picture is empty, missing, or an obsolete stock photo.
 */
export function getAvatarSrc(picture?: string | null): string {
  if (!picture || !picture.trim() || isLegacyStockAvatar(picture)) {
    return DEFAULT_CARTOON_AVATAR;
  }
  return picture.trim();
}
